// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.plannerimport com.roshan.persona.cognitive.model.Constraintimport com.roshan.persona.cognitive.model.ConstraintTypeimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Fuzzy Constraint Interpreter (Module 7 v2 — Step 7.3). * * Interprets fuzzy constraints ("budget-friendly", "fast", "comfortable") * into concrete bounds that the [com.roshan.persona.cognitive.engine.ProblemSolver] * can work with. * * ## Why fuzzy constraints? * * Users don't always give explicit numbers: *  - "budget-friendly" → needs interpretation (70th percentile of typical prices). *  - "fast" → needs interpretation (< 2 hours for travel, < 1s for responses). *  - "comfortable" → needs interpretation (4+ star rating for hotels). * * ## v1 approach * * For v1, we use a heuristic lookup table (no LLM needed). The table maps * common fuzzy phrases to concrete values. For unknown fuzzy phrases, we * return null (the ProblemSolver treats it as no constraint). * * Future (v3): LLM-based interpretation for unknown phrases. * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§FuzzyConstraintInterpreter</a> */class FuzzyConstraintInterpreter(    private val dispatcher: CoroutineDispatcher,) {    /**     * Interpret a fuzzy constraint into a concrete [Constraint].     *     * Handles the 3 strategy examples (§8 FuzzyConstraintInterpreter):     *  - "sometime next week" → date range Monday-Friday next week     *  - "around 500 rupees" → budget range 450-550     *  - "not too early" → after 9 AM     *     * @param fuzzyText the fuzzy text ("budget-friendly", "fast", "comfortable").     * @param contextType the constraint context (BUDGET, TIME, etc.) — helps disambiguate.     * @return a concrete constraint, or null if the fuzzy text can't be interpreted.     */    suspend fun interpret(        fuzzyText: String,        contextType: ConstraintType? = null,    ): Constraint? = withContext(dispatcher) {        val lower = fuzzyText.lowercase().trim()        // ─── Strategy §8 example 1: "sometime next week" → date range ───        // Matches "next week", "sometime next week", "next week sometime".        if (lower.contains("next week") || lower.contains("sometime next")) {            val (startMs, endMs) = nextWeekRange()            return@withContext Constraint(                type = ConstraintType.TIME,                value = "next_week_range",                isFuzzy = true,                description = "Next week (Mon-Fri): $startMs..$endMs",            )        }        // ─── Strategy §8 example 2: "around N rupees" → budget range ±10% ───        // Matches "around 500 rupees", "around ₹500", "approximately 500".        val aroundMatch = Regex("""(?:around|approximately|approx\.?)\s*(?:₹|rs\.?|rupees?)?\s*(\d+)""").find(lower)        if (aroundMatch != null) {            val amount = aroundMatch.groupValues[1].toIntOrNull() ?: return@withContext null            val lowerBound = (amount * 0.9f).toInt()  // 450 for 500            val upperBound = (amount * 1.1f).toInt()  // 550 for 500            return@withContext Constraint(                type = ConstraintType.BUDGET,                value = "around_$amount",                isFuzzy = true,                description = "Around $amount rupees (range: $lowerBound-$upperBound)",            )        }        // ─── Strategy §8 example 3: "not too early" → after 9 AM ───        if (lower.contains("not too early") || lower.contains("not early") || lower.contains("later in the morning")) {            return@withContext Constraint(                type = ConstraintType.TIME,                value = "after_9am",                isFuzzy = true,                description = "Not too early (after 9:00 AM)",            )        }        if (lower.contains("not too late") || lower.contains("not late") || lower.contains("earlier in the evening")) {            return@withContext Constraint(                type = ConstraintType.TIME,                value = "before_8pm",                isFuzzy = true,                description = "Not too late (before 8:00 PM)",            )        }        // Budget fuzzy constraints.        if (lower in BUDGET_FUZZY || (contextType == ConstraintType.BUDGET && lower.contains("budget"))) {            return@withContext Constraint(                type = ConstraintType.BUDGET,                value = "budget_friendly",                isFuzzy = true,                description = "Budget-friendly (70th percentile of typical prices)",            )        }        if (lower in PREMIUM_FUZZY || lower.contains("premium") || lower.contains("luxury")) {            return@withContext Constraint(                type = ConstraintType.BUDGET,                value = "premium",                isFuzzy = true,                description = "Premium (top 30th percentile)",            )        }        // Time/duration fuzzy constraints.        if (lower in FAST_FUZZY || lower.contains("fast") || lower.contains("quick")) {            return@withContext Constraint(                type = ConstraintType.TIME,                value = "fast",                isFuzzy = true,                description = "Fast (< 2 hours for travel, < 1s for responses)",            )        }        if (lower in SLOW_FUZZY || lower.contains("relaxed") || lower.contains("leisurely")) {            return@withContext Constraint(                type = ConstraintType.TIME,                value = "relaxed",                isFuzzy = true,                description = "Relaxed pace (no time pressure)",            )        }        // Quality fuzzy constraints.        if (lower in COMFORTABLE_FUZZY || lower.contains("comfortable") || lower.contains("cozy")) {            return@withContext Constraint(                type = ConstraintType.PREFERENCE,                value = "comfortable",                isFuzzy = true,                description = "Comfortable (4+ star rating or equivalent)",            )        }        if (lower.contains("best") || lower.contains("top") || lower.contains("premium quality")) {            return@withContext Constraint(                type = ConstraintType.PREFERENCE,                value = "best_quality",                isFuzzy = true,                description = "Best quality available",            )        }        // Location fuzzy constraints.        if (lower.contains("nearby") || lower.contains("close") || lower.contains("near me")) {            return@withContext Constraint(                type = ConstraintType.LOCATION,                value = "nearby",                isFuzzy = true,                description = "Nearby (within 5 km)",            )        }        // Unknown fuzzy phrase — return null.        null    }    /**     * Compute the next Monday-Friday date range as a pair of epoch ms.     *     * Returns (next Monday 00:00, next Friday 23:59:59).     */    private fun nextWeekRange(): Pair<Long, Long> {        val cal = java.util.Calendar.getInstance()        // Advance to next Monday.        while (cal.get(java.util.Calendar.DAY_OF_WEEK) != java.util.Calendar.MONDAY) {            cal.add(java.util.Calendar.DAY_OF_MONTH, 1)        }        cal.set(java.util.Calendar.HOUR_OF_DAY, 0)        cal.set(java.util.Calendar.MINUTE, 0)        cal.set(java.util.Calendar.SECOND, 0)        cal.set(java.util.Calendar.MILLISECOND, 0)        val startMs = cal.timeInMillis        // Advance to Friday end-of-day.        cal.set(java.util.Calendar.DAY_OF_WEEK, java.util.Calendar.FRIDAY)        cal.set(java.util.Calendar.HOUR_OF_DAY, 23)        cal.set(java.util.Calendar.MINUTE, 59)        cal.set(java.util.Calendar.SECOND, 59)        val endMs = cal.timeInMillis        return startMs to endMs    }    /**     * Check if [text] contains any fuzzy constraint phrases.     *     * Used by [com.roshan.persona.cognitive.engine.ProblemSolver] to detect     * whether fuzzy interpretation is needed.     */    fun isFuzzyPhrase(text: String): Boolean {        val lower = text.lowercase()        return ALL_FUZZY_PHRASES.any { lower.contains(it) }    }    companion object {        private val BUDGET_FUZZY = setOf("budget-friendly", "affordable", "cheap", "economical", "value for money")        private val PREMIUM_FUZZY = setOf("premium", "luxury", "high-end", "expensive")        private val FAST_FUZZY = setOf("fast", "quick", "rapid", "express")        private val SLOW_FUZZY = setOf("relaxed", "leisurely", "slow", "laid back")        private val COMFORTABLE_FUZZY = setOf("comfortable", "cozy", "spacious")        val ALL_FUZZY_PHRASES: Set<String> = BUDGET_FUZZY + PREMIUM_FUZZY + FAST_FUZZY + SLOW_FUZZY + COMFORTABLE_FUZZY +            setOf("best", "top", "nearby", "close", "near me", "premium quality")    }}